class Solution {
  private static int cost(char[] a, char[] b) {
    int[][] cnt = new int[26][26];
    int mism = 0;
    for (int t = 0; t < a.length; t++) {
      if (a[t] != b[t]) {
        cnt[a[t] - 'a'][b[t] - 'a']++;
        mism++;
      }
    }
    int swaps = 0;
    for (int x = 0; x < 26; x++)
      for (int y = x + 1; y < 26; y++) swaps += Math.min(cnt[x][y], cnt[y][x]);
    return mism - swaps;
  }

  public int minOperations(String word1, String word2) {
    int n = word1.length();
    int[] dp = new int[n + 1];
    java.util.Arrays.fill(dp, Integer.MAX_VALUE / 2);
    dp[0] = 0;
    for (int i = 0; i < n; i++) {
      for (int j = i; j < n; j++) {
        int len = j - i + 1;
        char[] a = word1.substring(i, j + 1).toCharArray(),
            b = word2.substring(i, j + 1).toCharArray();
        char[] r = new char[len];
        for (int t = 0; t < len; t++) r[t] = a[len - 1 - t];
        int c = Math.min(cost(a, b), 1 + cost(r, b));
        dp[j + 1] = Math.min(dp[j + 1], dp[i] + c);
      }
    }
    return dp[n];
  }
}
